impl<'a, C: Catalog> Planner<'a, C> {
    /// Creates a new planner.
    pub fn new(catalog: &'a C) -> Self {
        Planner { catalog }
    }

    /// Builds a plan for an AST statement.
    pub fn build(&mut self, statement: ast::Statement) -> Result<Plan> {
        match statement {
            ast::Statement::Begin { .. } => Ok(Plan::Begin),
            ast::Statement::Commit => Ok(Plan::Commit),
            ast::Statement::Rollback => Ok(Plan::Rollback),
            ast::Statement::Explain(stmt) => {
                let plan = self.build(*stmt)?;
                Ok(Plan::Explain(Box::new(plan)))
            }
            ast::Statement::CreateTable { name, columns } => self.build_create_table(name, columns),
            ast::Statement::DropTable { name, if_exists } => self.build_drop_table(name, if_exists),
            ast::Statement::Delete { table, r#where } => self.build_delete(table, r#where),
            ast::Statement::Insert { table, columns, values } => self.build_insert(table, columns, values),
            ast::Statement::Update { table, set, r#where } => self.build_update(table, set, r#where),
            ast::Statement::Select { select, from, r#where, group_by, having, order_by, offset, limit } => {
                self.build_select(select, from, r#where, group_by, having, order_by, offset, limit)
            }
        }
    }

    /// Builds a CREATE TABLE plan.
    fn build_create_table(&self, name: String, columns: Vec<ast::Column>) -> Result<Plan> {
        let mut table_columns = Vec::new();
        for col in columns {
            table_columns.push(Column {
                name: col.name,
                datatype: col.datatype,
                primary_key: col.primary_key,
                nullable: col.nullable.unwrap_or(true),
                default: col.default,
                unique: col.unique,
                index: col.index,
                references: col.references,
            });
        }
        let table = Table {
            name,
            columns: table_columns,
        };
        Ok(Plan::CreateTable(table))
    }

    /// Builds a DROP TABLE plan.
    fn build_drop_table(&self, name: String, if_exists: bool) -> Result<Plan> {
        Ok(Plan::DropTable { name, if_exists })
    }

    /// Builds a DELETE plan.
    fn build_delete(&self, table: String, r#where: Option<ast::Expression>) -> Result<Plan> {
        Ok(Plan::Delete { table, r#where })
    }

